begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000007901','archive-parent@test.local'),('00000000-0000-4000-8000-000000007902','archive-other@test.local'),('00000000-0000-4000-8000-000000007903',null);
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000007901','Archive A','00000000-0000-4000-8000-000000007901'),('10000000-0000-4000-8000-000000007902','Archive B','00000000-0000-4000-8000-000000007902');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000007901','00000000-0000-4000-8000-000000007901'),('10000000-0000-4000-8000-000000007902','00000000-0000-4000-8000-000000007902');
insert into public.children(id,family_id,name,grade) values('20000000-0000-4000-8000-000000007901','10000000-0000-4000-8000-000000007901','Ece',2),('20000000-0000-4000-8000-000000007902','10000000-0000-4000-8000-000000007901','Can',5);
insert into public.devices(id,family_id,auth_user_id,active_child_id) values('30000000-0000-4000-8000-000000007901','10000000-0000-4000-8000-000000007901','00000000-0000-4000-8000-000000007903','20000000-0000-4000-8000-000000007901');
insert into public.task_templates(id,family_id,child_id,title) values('40000000-0000-4000-8000-000000007901','10000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901','Read');
insert into public.task_completions(id,family_id,child_id,template_id,due_date,client_id) values('50000000-0000-4000-8000-000000007901','10000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901','40000000-0000-4000-8000-000000007901',current_date,gen_random_uuid());
insert into public.star_events(family_id,child_id,delta,reason,created_by) values('10000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901',12,'bonus','00000000-0000-4000-8000-000000007901');
insert into public.exams(id,family_id,child_id,title,subject,grade) values('60000000-0000-4000-8000-000000007901','10000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901','Historical','Matematik',2);
insert into public.child_shares(family_id,child_id,label,scopes,token_hash) values('10000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901','Teacher',array['grades'],extensions.digest('archive-test','sha256'));
insert into public.push_outbox(family_id,audience,kind,payload) values('10000000-0000-4000-8000-000000007901','parents','exam_finished',jsonb_build_object('exam_id','60000000-0000-4000-8000-000000007901'));
set local role authenticated;
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000007901", "role": "authenticated", "gina": {"family_id": "10000000-0000-4000-8000-000000007901", "role": "parent"}}',true);
select is(public.get_child_archive_preview('20000000-0000-4000-8000-000000007901')->>'routines','1','preview active routines');
select is(public.get_child_archive_preview('20000000-0000-4000-8000-000000007901')->>'devices','1','preview all-mode device');
select is(public.get_child_archive_preview('20000000-0000-4000-8000-000000007901')->>'stars','12','earned total preview');
select lives_ok($$select public.save_school_timetable('20000000-0000-4000-8000-000000007901',0,'[{"id":"math","day":1,"title":"Matematik","start":"09:00","end":"09:40"}]','{"start":"09:00","duration":40,"break":10}')$$,'existing timetable saved');
select throws_ok($$update public.children set archived_at=now() where id='20000000-0000-4000-8000-000000007901'$$,'P0001','child_archive_use_action','direct projection bypass rejected');
select lives_ok($$select public.set_child_archived('70000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901',0,true)$$,'archive commits atomically');
select lives_ok($$select public.set_child_archived('70000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901',0,true)$$,'same request safe replay');
select is((select archive_revision from public.children where id='20000000-0000-4000-8000-000000007901'),1,'no repeated revision');
select is((select active from public.task_templates where id='40000000-0000-4000-8000-000000007901'),false,'routines paused');
select is((select count(*)::int from public.exams where child_id='20000000-0000-4000-8000-000000007901'),1,'exam history preserved');
select is((select sum(delta)::int from public.star_events where child_id='20000000-0000-4000-8000-000000007901'),12,'stars preserved');
select is((select jsonb_array_length(lessons) from public.school_timetables where child_id='20000000-0000-4000-8000-000000007901'),1,'timetable preserved');
select is((select count(*)::int from public.child_shares where child_id='20000000-0000-4000-8000-000000007901' and revoked_at is null),0,'share links revoked');
select is(gina.device_allows('30000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901'),false,'archive blocks all-mode device');
select is(gina.device_allows('30000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007902'),true,'sibling device access unaffected');
select is(jsonb_array_length(public.get_child_device_access('30000000-0000-4000-8000-000000007901')->'children'),1,'device settings omit archived profile');
select throws_ok($$select public.verify_child_pin('20000000-0000-4000-8000-000000007901','')$$,'P0001','child_archived','parent-mode entry denied');
select throws_ok($$select public.configure_child_device('30000000-0000-4000-8000-000000007901','Tablet',array['20000000-0000-4000-8000-000000007901']::uuid[],false)$$,'P0001','child_not_found','cannot configure archived child');
select throws_ok($$update public.children set name='Changed' where id='20000000-0000-4000-8000-000000007901'$$,'P0001','child_archived','archived profile cannot be edited');
select throws_ok($$insert into public.task_templates(family_id,child_id,title) values('10000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901','New')$$,'P0001','child_archived','new assignment denied');
select throws_ok($$update public.task_templates set active=true where id='40000000-0000-4000-8000-000000007901'$$,'P0001','child_archived','cannot resume archived routine');
select throws_ok($$update public.task_templates set child_id='20000000-0000-4000-8000-000000007902' where id='40000000-0000-4000-8000-000000007901'$$,'P0001','child_archived','cannot move archived history to sibling');
select throws_ok($$delete from public.task_templates where id='40000000-0000-4000-8000-000000007901'$$,'P0001','child_archived','direct destructive history edit denied');
select throws_ok($$select public.set_child_archived(gen_random_uuid(),'20000000-0000-4000-8000-000000007901',0,false)$$,'P0001','archive_changed','stale restore rejected');
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000007903", "role": "authenticated", "gina": {"family_id": "10000000-0000-4000-8000-000000007901", "role": "device", "device_id": "30000000-0000-4000-8000-000000007901", "child_id": "20000000-0000-4000-8000-000000007901"}}',true);
select is(gina.is_device(),false,'stale child JWT immediately denied');
select is((select count(*)::int from public.exams),0,'stale device cannot read exams');
select throws_ok($$select public.child_pin_login('20000000-0000-4000-8000-000000007901','')$$,'42501','forbidden','device cannot reenter archived child');
select throws_ok($$select public.set_child_archived(gen_random_uuid(),'20000000-0000-4000-8000-000000007901',1,false)$$,'42501','archive_forbidden','child cannot restore own profile');
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000007902", "role": "authenticated", "gina": {"family_id": "10000000-0000-4000-8000-000000007902", "role": "parent"}}',true);
select throws_ok($$select public.get_child_archive_preview('20000000-0000-4000-8000-000000007901')$$,'42501','archive_forbidden','other family cannot preview');
select throws_ok($$select public.set_child_archived(gen_random_uuid(),'20000000-0000-4000-8000-000000007901',1,false)$$,'42501','archive_forbidden','other family cannot restore');
reset role;
select is((select active_child_id from public.devices where id='30000000-0000-4000-8000-000000007901'),null::uuid,'device active identity cleared');
select is((select count(*)::int from public.push_outbox where family_id='10000000-0000-4000-8000-000000007901' and status in('pending','sending')),0,'completion and exam pending notifications cancelled');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.reserve_child_ai_operation('10000000-0000-4000-8000-000000007901','00000000-0000-4000-8000-000000007901','plan','hash',gen_random_uuid(),'20000000-0000-4000-8000-000000007901')$$,'P0001','child_archived','AI blocked before provider reservation');
reset role;
select is((select count(*)::int from public.ai_operation_jobs where family_id='10000000-0000-4000-8000-000000007901'),0,'archive gate consumes no quota or job');
set local role authenticated;
select set_config('request.jwt.claims','{"sub": "00000000-0000-4000-8000-000000007901", "role": "authenticated", "gina": {"family_id": "10000000-0000-4000-8000-000000007901", "role": "parent"}}',true);
select lives_ok($$select public.set_child_archived(gen_random_uuid(),'20000000-0000-4000-8000-000000007901',1,false)$$,'restore same identity');
select is((select archive_revision from public.children where id='20000000-0000-4000-8000-000000007901'),2,'restore revision');
select is((select active from public.task_templates where id='40000000-0000-4000-8000-000000007901'),false,'restore does not resume routines');
select is(gina.device_allows('30000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901'),false,'restore does not regrant all-mode device');
select is((select count(*)::int from public.child_shares where child_id='20000000-0000-4000-8000-000000007901' and revoked_at is null),0,'restore does not revive shares');
select lives_ok($$select public.configure_child_device('30000000-0000-4000-8000-000000007901','Tablet',array['20000000-0000-4000-8000-000000007901']::uuid[],false)$$,'explicit parent regrant');
select is(gina.device_allows('30000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901'),true,'explicit configuration enables access');
select lives_ok($$select public.set_child_archived(gen_random_uuid(),'20000000-0000-4000-8000-000000007901',2,true)$$,'selected-mode archive');
select is(gina.device_allows('30000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901'),false,'selected-mode access removed');
select lives_ok($$select public.set_child_archived(gen_random_uuid(),'20000000-0000-4000-8000-000000007901',3,false)$$,'second restore');
select is(gina.device_allows('30000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007901'),false,'selected-mode access does not revive');
select ok(not has_function_privilege('anon','public.set_child_archived(uuid,uuid,integer,boolean)','execute'),'anon cannot archive');
select ok(not has_function_privilege('authenticated','public.reserve_child_ai_operation(uuid,uuid,text,text,uuid,uuid)','execute'),'client cannot reserve provider operation');
select ok(not has_table_privilege('authenticated','gina.child_archive_state','update'),'client cannot bypass private state');
select lives_ok($$select public.set_child_archived(gen_random_uuid(),'20000000-0000-4000-8000-000000007901',4,true)$$,'archive for deletion test');
select lives_ok($$delete from public.children where id='20000000-0000-4000-8000-000000007901'$$,'explicit permanent child deletion still cascades');
reset role;
select is((select count(*)::int from public.exams where child_id='20000000-0000-4000-8000-000000007901'),0,'permanent deletion removes historical exam');
select is((select count(*)::int from gina.child_archive_state where child_id='20000000-0000-4000-8000-000000007901'),0,'archive metadata follows deletion');
select is((select count(*)::int from public.children where id='20000000-0000-4000-8000-000000007902'),1,'sibling preserved');
insert into public.star_events(family_id,child_id,delta,reason,created_by) values('10000000-0000-4000-8000-000000007901','20000000-0000-4000-8000-000000007902',7,'bonus','00000000-0000-4000-8000-000000007901');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000007901','00000000-0000-4000-8000-000000007902');
select public.set_child_archived(gen_random_uuid(),'20000000-0000-4000-8000-000000007902',0,true);
select lives_ok($$delete from auth.users where id='00000000-0000-4000-8000-000000007901'$$,'deleting one parent preserves archived child for remaining parent');
select is((select sum(delta)::int from public.star_events where child_id='20000000-0000-4000-8000-000000007902'),7,'parent deletion retains earned stars');
select lives_ok($$delete from auth.users where id='00000000-0000-4000-8000-000000007902'$$,'last parent account cleanup includes archived children');
select is((select count(*)::int from public.children where id='20000000-0000-4000-8000-000000007902'),0,'last parent cleanup removes child');
select * from finish();rollback;
